changeSet.sql:
-- Skip-locked claim pattern reads from this index:
--   SELECT * FROM EXCEPTION_QUEUE
--   WHERE STATUS = 'OPEN' ORDER BY CREATED_AT
--   FETCH FIRST :n ROWS ONLY FOR UPDATE SKIP LOCKED;
CREATE INDEX TFPM_ADDR_ENRICH.IX_EXC_OPEN
    ON TFPM_ADDR_ENRICH.EXCEPTION_QUEUE (STATUS, CREATED_AT);

CREATE INDEX TFPM_ADDR_ENRICH.IX_EXC_RESULT
    ON TFPM_ADDR_ENRICH.EXCEPTION_QUEUE (RESULT_ID);
